for (Cell cell : row) {
    String desc = switch (cell.getCellType()) {
        case STRING -> cell.getStringCellValue();
        case NUMERIC -> String.valueOf(cell.getNumericCellValue());
        case BOOLEAN -> String.valueOf(cell.getBooleanCellValue());
        case FORMULA -> "formula: " + cell.getCellFormula();
        default -> "?";
    };
}

// BLAD: nowy CellStyle tworzony w KAZDEJ iteracji petli
for (int i = 0; i < 1000; i++) {
    CellStyle style = workbook.createCellStyle(); // NOWY styl za kazdym razem!
    style.setBorderBottom(BorderStyle.THIN);
    Row row = sheet.createRow(i);
    row.createCell(0).setCellStyle(style);
}

// POPRAWNIE: CellStyle utworzony RAZ, reuzywany dla wszystkich komorek
CellStyle borderedStyle = workbook.createCellStyle();
borderedStyle.setBorderBottom(BorderStyle.THIN);

for (int i = 0; i < 1000; i++) {
    Row row = sheet.createRow(i);
    row.createCell(0).setCellStyle(borderedStyle); // TEN SAM styl, wielokrotnie
}
